function fetchBasecampTodo(url) {
  const token = getBasecampToken();

  const match = url.match(/3\.basecamp\.com\/(\d+)\/buckets\/(\d+)\/todos\/(\d+)/);
  if (!match) throw new Error('Invalid Basecamp todo URL. Must be a /todos/ page.');
  const [, accountId, bucketId, todoId] = match;

  const headers = {
    Authorization: 'Bearer ' + token,
    'User-Agent': 'DR Task Logger (richardvargasdesigns@gmail.com)',
  };

  const todo = JSON.parse(
    UrlFetchApp.fetch(
      `https://3.basecamp.com/${accountId}/buckets/${bucketId}/todos/${todoId}.json`,
      { headers }
    ).getContentText()
  );

  const commentsRaw = UrlFetchApp.fetch(
    `https://3.basecamp.com/${accountId}/buckets/${bucketId}/recordings/${todoId}/comments.json`,
    { headers, muteHttpExceptions: true }
  ).getContentText();
  const comments = JSON.parse(commentsRaw);

  let pdd = '', hdd = '', est = '';

  if (Array.isArray(comments)) {
    // Walk from newest comment backwards to find the most recent one with scheduling info
    for (let i = comments.length - 1; i >= 0; i--) {
      const text = stripHtml(comments[i].content || '');
      const pddM  = text.match(/PDD:\s*(\d+\/\d+)/i);
      const hddM  = text.match(/HDD:\s*(\d+\/\d+)/i);
      const estRM = text.match(/EST:\s*[\d.]+\s*[-–]\s*([\d.]+)\s*hrs?/i);
      const estSM = text.match(/EST:\s*([\d.]+)\s*hrs?/i);

      if (pddM || hddM || estRM || estSM) {
        if (pddM)       pdd = pddM[1];
        if (hddM)       hdd = hddM[1];
        if (estRM)      est = estRM[1];

