// ─── Constants ────────────────────────────────────────────────────────────────
const SHEET_GID        = 1970451898;
const BC_CLIENT_ID     = '38b03859297d1a9b0dd52b7754ef09d45cd125dc';
const BC_CLIENT_SECRET = 'f9fa64d922cf3e122d08b0ea233d1782c0df7ecd';
const BC_REDIRECT_URI  = 'http://localhost:8080/callback';

// ─── Menu ─────────────────────────────────────────────────────────────────────
function onOpen() {
  SpreadsheetApp.getUi()
    .createMenu('DR Tools')
    .addItem('Log Basecamp Task', 'showSidebar')
    .addToUi();
}

function showSidebar() {
  const html = HtmlService.createHtmlOutputFromFile('Sidebar')
    .setTitle('Log Basecamp Task')
    .setWidth(340);
