// ─── Token management ─────────────────────────────────────────────────────────
function getBasecampToken() {
  const props  = PropertiesService.getScriptProperties();
  const access  = props.getProperty('BC_ACCESS_TOKEN');
  const refresh = props.getProperty('BC_REFRESH_TOKEN');

  if (!access || !refresh) {
    throw new Error('Basecamp not authorized. Run the one-time setup (get_token.py) and add tokens to Script Properties.');
  }

  const expiry = parseInt(props.getProperty('BC_TOKEN_EXPIRY') || '0');
  if (Date.now() < expiry - 300000) return access; // still valid

  // Refresh
  const res = UrlFetchApp.fetch('https://launchpad.37signals.com/authorization/token', {
    method: 'post',
    contentType: 'application/x-www-form-urlencoded',
    payload: {
      type:          'refresh',
      refresh_token: refresh,
      client_id:     BC_CLIENT_ID,
      client_secret: BC_CLIENT_SECRET,
      redirect_uri:  BC_REDIRECT_URI,
    },
  });
  const data = JSON.parse(res.getContentText());
  props.setProperty('BC_ACCESS_TOKEN',  data.access_token);
  props.setProperty('BC_TOKEN_EXPIRY',  String(Date.now() + data.expires_in * 1000));
  return data.access_token;
}

// ─── Fetch todo data ──────────────────────────────────────────────────────────
function fetchBasecampTodo(url) {
  const token = getBasecampToken();

  const match = url.match(/3\.basecamp\.com\/(\d+)\/buckets\/(\d+)\/todos\/(\d+)/);
  if (!match) throw new Error('Invalid Basecamp todo URL. Must be a /todos/ page.');
  const [, accountId, bucketId, todoId] = match;

  const headers = {
    Authorization: 'Bearer ' + token,
    'User-Agent': 'DR Task Logger (richardvargasdesigns@gmail.com)',
  };

  const todo = JSON.parse(
    UrlFetchApp.fetch(
      `https://3.basecamp.com/${accountId}/buckets/${bucketId}/todos/${todoId}.json`,
      { headers }
    ).getContentText()
  );

  const commentsRaw = UrlFetchApp.fetch(
    `https://3.basecamp.com/${accountId}/buckets/${bucketId}/recordings/${todoId}/comments.json`,
    { headers, muteHttpExceptions: true }
  ).getContentText();
  const comments = JSON.parse(commentsRaw);

  let pdd = '', hdd = '', est = '';

  if (Array.isArray(comments)) {
    // Walk from newest comment backwards to find the most recent one with scheduling info
    for (let i = comments.length - 1; i >= 0; i--) {
      const text = stripHtml(comments[i].content || '');
      const pddM  = text.match(/PDD:\s*(\d+\/\d+)/i);
      const hddM  = text.match(/HDD:\s*(\d+\/\d+)/i);
      const estRM = text.match(/EST:\s*[\d.]+\s*[-–]\s*([\d.]+)\s*hrs?/i);
      const estSM = text.match(/EST:\s*([\d.]+)\s*hrs?/i);

      if (pddM || hddM || estRM || estSM) {
        if (pddM)       pdd = pddM[1];
        if (hddM)       hdd = hddM[1];
        if (estRM)      est = estRM[1];
        else if (estSM) est = estSM[1];
        break;
      }
    }
  }

  const clientName    = todo.bucket.name.replace(/\s*\([^)]*\)\s*/g, '').trim();
  const assignedTo    = todo.assignees && todo.assignees.length ? todo.assignees[0].name : '';
  const todolistName  = todo.parent ? todo.parent.title : '';
  const projectType   = inferProjectType(todo.title, todo.bucket.name, todolistName);
  const priority      = /\[PRIORITY/i.test(todo.title);
  const monthAssigned = pdd ? buildMonthAssigned(pdd) : '';

  return {
    url,
    clientName,
    title:         todo.title,
    assignedTo,
    pdd:           pdd ? appendYear(pdd) : '',
    hdd:           hdd ? appendYear(hdd) : '',
    est,
    projectType,
    priority,
    monthAssigned,
  };
}

// ─── Append row ───────────────────────────────────────────────────────────────
function appendToSheet(data) {
  const ss    = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheets().find(s => s.getSheetId() === SHEET_GID);
  if (!sheet) throw new Error('Target sheet not found (gid ' + SHEET_GID + ').');

  const estHours = data.est ? parseFloat(data.est) : null;

  // Column order matches the sheet header exactly:
  // Client Name | Project Links | Project Type | Priority | Assigned | Date Assigned |
  // HDD | Approved | Approved Date | Primary | Partner | Task Description |
  // Value | Canceled | Time (Estimated) | Time (Actual) | Time Difference |
  // Project Open Period | Month Assigned | Service Type
  const row = [
    data.clientName,
    data.url,
    data.projectType,
    data.priority,
    false,
    data.pdd ? new Date(data.pdd) : '',
    data.hdd ? new Date(data.hdd) : '',
    false,
    '',
    data.assignedTo,
    '',
    data.title,
    false,
    false,
    estHours !== null ? estHours / 24 : '',
    '',
    '',
    '',
    data.monthAssigned,
    '',
  ];

  sheet.appendRow(row);
  const lastRow = sheet.getLastRow();

  if (data.pdd) sheet.getRange(lastRow, 6).setNumberFormat('M/D/YYYY');
  if (data.hdd) sheet.getRange(lastRow, 7).setNumberFormat('M/D/YYYY');
  if (estHours !== null) sheet.getRange(lastRow, 15).setNumberFormat('[h]:mm');

  return lastRow;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────
function stripHtml(html) {
  return html
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .trim();
}

function appendYear(dateStr) {
  return dateStr + '/' + new Date().getFullYear();
}

function buildMonthAssigned(pdd) {
  const month = parseInt(pdd.split('/')[0]);
  const year  = new Date().getFullYear();
  const names = ['January','February','March','April','May','June',
                 'July','August','September','October','November','December'];
  return `${month} | ${names[month - 1]} ${year}`;
}

function inferProjectType(title, bucketName, todolistName) {
  const t = (title + ' ' + bucketName + ' ' + todolistName).toLowerCase();

  if (/brand|logo/.test(t))                              return 'Branding/Logo - Creation/Edits';
  if (/print|collateral|packag|flyer|brochure/.test(t)) return 'Print - Collateral/Packaging';
  if (/banner|display ad/.test(t))                      return 'Digital - Banner/Display Ads';
  if (/\bemail\b|newsletter|e-blast|signature/.test(t)) return 'Email - Campaigns/Signatures';
  if (/\bipm\b/.test(t))                                return 'IPM - Campaigns/Reports';
  if (/\bsm\b|social media|reel|instagram|tiktok/.test(t)) return 'SM - templates/graphics/reels';
  if (/photo|video/.test(t))                            return 'Multi - Photo/Video/Edits';
  if (/\badmin\b/.test(t))                              return 'Admin';

  if (/\blp\b|landing page/.test(t)) {
    return /mainten|edit|update|fix|change|remov|add |adjust|launch/.test(t)
      ? 'LP - Maintenance'
      : 'LP - New';
  }

  if (/website|web build|web redesign|mockup|\bui\b|application/.test(t)) {
    return /mainten|update|edit|fix|change|remov|add |adjust/.test(t)
      ? 'Web - Maintenance'
      : 'Web - Sites/Applications/UI';
  }

  return 'Misc.';
}

