  if (/\bsm\b|social media|reel|instagram|tiktok/.test(t)) return 'SM - templates/graphics/reels';
  if (/photo|video/.test(t))                            return 'Multi - Photo/Video/Edits';
  if (/\badmin\b/.test(t))                              return 'Admin';

  if (/\blp\b|landing page/.test(t)) {
    return /mainten|edit|update|fix|change|remov|add |adjust|launch/.test(t)
