      : 'LP - New';
  }

  if (/website|web build|web redesign|mockup|\bui\b|application/.test(t)) {
    return /mainten|update|edit|fix|change|remov|add |adjust/.test(t)
      ? 'Web - Maintenance'
      : 'Web - Sites/Applications/UI';
